-- ======================================================================
--  IRON LEAGUE — a rest day in one league no longer shuts the others
--
--  Paste the whole file into the Supabase SQL editor and press RUN, or apply
--  it over the API. Safe to run twice. NOTHING LOGGED IS TOUCHED and no
--  points are rewritten.
--
--  GENERATED by tools/build_restday_migration.py, which lifts all three
--  functions below out of supabase/schema.sql. Edit there and re-run it,
--  never here.
--
--  THE BUG
--  A rest day belongs to a league, and a person can be in several.
--  log_workout() writes one row per league the person is in, and the rest
--  rule raised from the insert trigger. A raise from any one of those rows
--  aborts the whole statement — so while ONE league was resting, somebody in
--  two could not log anything at all, and the league that was open lost the
--  entry too. One league closing its own Sunday should close that league, not
--  the person's day.
--
--  THE FIX
--  The rule is now a question before it is a rule:
--
--    rest_day_block()  why this league will not take this entry, or null
--    rest_day_check()  the same answer as a raise, for the triggers
--
--  log_workout() filters the fan-out on the question, so the leagues that are
--  open score the entry and the resting ones sit it out. It raises only when
--  EVERY league refuses — with the reason the league on screen gives, which
--  keeps the message exactly what it has always been for somebody in one
--  league. It also hands back a row from whichever league did take it, so the
--  app still has a points figure to show when the screen you logged from is
--  the one resting.
--
--  The triggers still call rest_day_check(), so a row written directly — an
--  edit, or anything not coming through the RPC — is refused exactly as
--  before. The one-recovery-a-day rule and the one-session cap on a stretch
--  are per league and unchanged.
-- ======================================================================
begin;
set local check_function_bodies = off;

-- -------------------------------------------------------- rest_day_block ---
create or replace function public.rest_day_block(
  p_profile uuid, p_league uuid, p_key text, p_at timestamptz, p_exclude uuid)
returns text language plpgsql stable set search_path = public as $fn$
declare
  tz   text := public.app_timezone();
  dows int[] := coalesce((select rest_dow from public.leagues where id = p_league), '{7}'::int[]);
  d    date;
begin
  if not (extract(isodow from (p_at at time zone tz))::int = any (dows)) then return null; end if;
  if p_key <> 'stretch' then return 'REST_DAY'; end if;
  d := (p_at at time zone tz)::date;
  if exists (
    select 1 from public.workouts w
    where w.profile_id = p_profile
      and w.league_id  = p_league
      and (w.created_at at time zone tz)::date = d
      and (p_exclude is null or w.id <> p_exclude)
  ) then
    return 'REST_DAY_DONE';
  end if;
  return null;
end $fn$;

-- -------------------------------------------------------- rest_day_check ---
create or replace function public.rest_day_check(
  p_profile uuid, p_league uuid, p_key text, p_at timestamptz, p_exclude uuid)
returns void language plpgsql stable set search_path = public as $fn$
declare why text;
begin
  why := public.rest_day_block(p_profile, p_league, p_key, p_at, p_exclude);
  if why is not null then raise exception '%', why; end if;
end $fn$;

-- ----------------------------------------------------------- log_workout ---
create or replace function public.log_workout(
  p_league uuid, p_key text, p_mode text, p_amount numeric,
  p_bw numeric default null, p_load numeric default null)
returns table (id uuid, group_id uuid, exercise_key text, mode text,
               amount numeric, points numeric, leagues int)
language plpgsql security definer set search_path = public as $fn$
declare
  me uuid := public.my_profile_id();
  g  uuid := gen_random_uuid();
  n  int;
begin
  if me is null then raise exception 'NO_PROFILE'; end if;
  if not public.is_member(p_league) then raise exception 'NOT_A_MEMBER'; end if;
  -- Remember the bodyweight so nobody retypes it every gym set.
  if p_bw is not null and p_bw between 30 and 250 then
    update public.profiles set bodyweight = p_bw where profiles.id = me;
  end if;

  -- One row per league, but only the leagues that will take it. A rest day
  -- belongs to a league: the ones resting sit this entry out and the rest of
  -- them score it. Filtering here rather than letting the trigger raise is
  -- the whole fix — a raise from any one row aborts the statement, so one
  -- league's Sunday used to cost somebody every league they were in.
  insert into public.workouts (group_id, league_id, profile_id,
                               exercise_key, mode, amount, bodyweight, load)
  select g, m.league_id, me, p_key, p_mode, p_amount, p_bw, p_load
  from public.league_members m
  where m.profile_id = me
    and public.rest_day_block(me, m.league_id, p_key, now(), null) is null;
  get diagnostics n = row_count;

  -- Nothing took it, so every league this person is in is shut today. Now the
  -- rest day really has stopped them, and they get the reason the league they
  -- were looking at gives — which keeps the message exactly what it has
  -- always been for somebody in one league.
  if n = 0 then
    raise exception '%', coalesce(
      public.rest_day_block(me, p_league, p_key, now(), null), 'REST_DAY');
  end if;

  -- The row for the league on screen, or any of them when that is the one
  -- sitting the day out: the app needs a points figure to show either way.
  return query
  select w.id, w.group_id, w.exercise_key, w.mode, w.amount, w.points, n
  from public.workouts w
  where w.group_id = g
  order by (w.league_id = p_league) desc
  limit 1;
end $fn$;

-- -------------------------------------------------------- grants ---
revoke all on function public.log_workout(uuid,text,text,numeric,numeric,numeric) from public, anon;
revoke all on function public.rest_day_block(uuid,uuid,text,timestamptz,uuid) from public, anon;
grant execute on function public.log_workout(uuid,text,text,numeric,numeric,numeric) to authenticated;

commit;

